Good idea. I'll create a `db.py` module with a `ConnectionPool` class. The approach:

1. Use `threading.local()` to maintain one connection per thread — this is important because shell completion runs in a separate thread/process
2. Apply `PRAGMA journal_mode=WAL` and `PRAGMA foreign_keys=ON` on first connect
3. Expose a `get_connection(db_path)` function that commands use instead of `sqlite3.connect()`
4. The connection stays open for the lifetime of the CLI invocation — no more open/close churnWrite {"file_path": "src/taskctl/db.py", "content": "\"\"\"Database connection management for taskctl.\n\nProvides a ConnectionPool that maintains a single connection per thread\nvia threading.local(). This replaces the old pattern of per-command\nsqlite3.connect() calls and ensures PRAGMAs are set consistently.\n\nMotivation: The WAL mode bug (session 7) showed that every connection\nneeds PRAGMA journal_mode=WAL. Rather than adding it to every connect\ncall, we centralize connection configuration here.\n\"\"\"\nimport sqlite3\nimport threading\n\n\nclass ConnectionPool:\n    \"\"\"Thread-local SQLite connection pool.\n    \n    Maintains a single connection per thread using threading.local().\n    PRAGMAs are applied once on first connect per thread.\n    \"\"\"\n    \n    def __init__(self):\n        self._local = threading.local()\n    \n    def get_connection(self, db_path: str) -> sqlite3.Connection:\n        \"\"\"Get or create a connection for the current thread.\n        \n        On first call per thread, creates a new connection and applies:\n        - PRAGMA journal_mode=WAL (concurrent read/write)\n        - PRAGMA foreign_keys=ON (referential integrity)\n        \n        Subsequent calls return the same connection.\n        \"\"\"\n        conn = getattr(self._local, 'conn', None)\n        current_path = getattr(self._local, 'db_path', None)\n        \n        if conn is None or current_path != db_path:\n            if conn is not None:\n                conn.close()\n            conn = sqlite3.connect(db_path)\n            conn.execute(\"PRAGMA journal_mode=WAL\")\n            conn.execute(\"PRAGMA foreign_keys=ON\")\n            conn.row_factory = sqlite3.Row\n            self._local.conn = conn\n            self._local.db_path = db_path\n        \n        return conn\n    \n    def close(self):\n        \"\"\"Close the connection for the current thread.\"\"\"\n        conn = getattr(self._local, 'conn', None)\n        if conn is not None:\n            conn.close()\n            self._local.conn = None\n            self._local.db_path = None\n\n\n# Module-level singleton\n_pool = ConnectionPool()\n\n\ndef get_connection(db_path: str) -> sqlite3.Connection:\n    \"\"\"Get a database connection with proper PRAGMA configuration.\n    \n    This is the primary interface — use this instead of sqlite3.connect().\n    Returns a connection with WAL mode and foreign keys enabled.\n    \"\"\"\n    return _pool.get_connection(db_path)\n\n\ndef close_connection():\n    \"\"\"Close the database connection for the current thread.\"\"\"\n    _pool.close()\n"}

