I'll use `PRAGMA user_version` — it's a built-in SQLite integer that persists across connections. Much simpler than a migrations table with `applied_at` timestamps or an Alembic-style chain. Migration files are named `NNN_description.sql` (e.g., `001_initial_schema.sql`, `002_add_priority.sql`) stored in `migrations/`. On startup, the app reads the current `user_version`, finds all migration files with a number greater than that version, applies them in order within a transaction, and updates `user_version` to the highest applied number.Write {"file_path": "src/taskctl/migrate.py", "content": "\"\"\"Database migration system using PRAGMA user_version.\"\"\"\nimport os\nimport re\nimport sqlite3\nfrom pathlib import Path\n\nMIGRATIONS_DIR = Path(__file__).parent.parent.parent / \"migrations\"\n\n\ndef get_migration_files(migrations_dir: Path = MIGRATIONS_DIR) -> list[tuple[int, Path]]:\n    \"\"\"Return sorted list of (version, path) for migration files.\"\"\"\n    pattern = re.compile(r\"^(\\d{3})_.*\\.sql$\")\n    migrations = []\n    for f in sorted(migrations_dir.iterdir()):\n        m = pattern.match(f.name)\n        if m:\n            migrations.append((int(m.group(1)), f))\n    return sorted(migrations, key=lambda x: x[0])\n\n\ndef apply_migrations(db_path: str, migrations_dir: Path = MIGRATIONS_DIR) -> int:\n    \"\"\"Apply pending migrations and return the new schema version.\n    \n    Migrations are tracked via SQLite PRAGMA user_version. On startup,\n    we read the current user_version, find all migration files with a\n    number greater than that version, apply them in order within a\n    transaction, and update user_version to the highest applied number.\n    \"\"\"\n    conn = sqlite3.connect(db_path)\n    current_version = conn.execute(\"PRAGMA user_version\").fetchone()[0]\n    \n    migrations = get_migration_files(migrations_dir)\n    applied = 0\n    \n    for version, path in migrations:\n        if version > current_version:\n            sql = path.read_text()\n            conn.executescript(sql)\n            conn.execute(f\"PRAGMA user_version = {version}\")\n            applied += 1\n    \n    conn.commit()\n    conn.close()\n    return current_version + applied\n"}

